body.script:
function toggleTheme() {
    const current = document.documentElement.getAttribute('data-theme') || 'light';
    const next = current === 'dark' ? 'light' : 'dark';
    document.documentElement.setAttribute('data-theme', next);
    localStorage.setItem('beauty_theme', next);
    updateThemeIcon(next);
}
function updateThemeIcon(theme) {
    document.querySelectorAll('.themeToggleIcon, #themeToggleIcon').forEach(icon => {
        icon.className = theme === 'dark' ? 'themeToggleIcon fa fa-sun-o' : 'themeToggleIcon fa fa-moon-o';
    });
}
(function() {
    const saved = localStorage.getItem('beauty_theme') || 'light';
    document.documentElement.setAttribute('data-theme', saved);
    window.addEventListener('DOMContentLoaded', () => updateThemeIcon(saved));
})();
// Automatically show transaction status pop-up if present, and clean the URL
window.addEventListener('DOMContentLoaded', function() {
    const txnModalEl = document.getElementById('transactionStatusModal');
    if (txnModalEl && typeof bootstrap !== 'undefined') {
        const txnModal = new bootstrap.Modal(txnModalEl);
        txnModal.show();
        // Clean up the URL parameters so the transaction message doesn't linger in the address bar
        if (window.history && window.history.replaceState) {
            window.history.replaceState({}, document.title, window.location.pathname);
        }
    }
});

