function toggleTheme() {
    const html = document.documentElement;
    const current = html.getAttribute('data-theme') || 'light';
    const next = current === 'dark' ? 'light' : 'dark';
    html.setAttribute('data-theme', next);
    localStorage.setItem('theme', next);
    updateThemeIcons(next);
}
function updateThemeIcons(theme) {
    document.querySelectorAll('.themeToggleIcon').forEach(el => {
        el.className = theme === 'dark' ? 'themeToggleIcon fa fa-sun-o' : 'themeToggleIcon fa fa-moon-o';
    });
}
(function() {
    const saved = localStorage.getItem('theme') || 'light';
    document.documentElement.setAttribute('data-theme', saved);
    document.addEventListener('DOMContentLoaded', () => updateThemeIcons(saved));
})();

function updateSubFields(subId, method) {
    const label = document.getElementById('sub_phone_label_' + subId);
    const helper = document.getElementById('sub_phone_helper_' + subId);
    const input = document.getElementById('sub_phone_input_' + subId);
    ['ecocash', 'onemoney', 'visa'].forEach(m => {
        const card = document.getElementById('sub_card_' + m + '_' + subId);
        if (card) card.style.borderColor = 'var(--border-color)';
    });
    const activeCard = document.getElementById('sub_card_' + method + '_' + subId);
    if (activeCard) activeCard.style.borderColor = 'var(--accent)';

    if (method === 'ecocash') {
        if (label) label.innerText = 'EcoCash Mobile Number *';
        if (helper) helper.innerText = 'A USSD push prompt will be sent to your EcoCash phone to approve.';
        if (input) { input.placeholder = 'e.g. 0771234567'; input.required = true; }
    } else if (method === 'onemoney') {
        if (label) label.innerText = 'OneMoney Mobile Number *';
        if (helper) helper.innerText = 'A NetOne PIN prompt will be sent to your OneMoney phone to approve.';
        if (input) { input.placeholder = 'e.g. 0712345678'; input.required = true; }
    } else if (method === 'card') {
        if (label) label.innerText = 'Contact Phone for Visa/Mastercard (Optional)';
        if (helper) helper.innerText = 'You will securely input your card details on Pesepay checkout.';
        if (input) { input.placeholder = 'e.g. +263...'; input.required = false; }
    }
}

